            S("(b) Integrate to a logarithm, divide by 2", math=r"\int \frac{1}{2x + 3}\,dx = \frac{1}{2}\ln|2x + 3|"),
            S("(b) Substitute the limits", math=r"\frac{1}{2}\ln 7 - \frac{1}{2}\ln 3"),
