            S("Integrate", math=r"\int 40e^{-0.1t}\,dt = \frac{40}{-0.1}e^{-0.1t} = -400e^{-0.1t}"),
            S("Substitute the limits", math=r"V = \left[-400e^{-0.1t}\right]_0^{10} = -400e^{-1} + 400"),
